 putenv('KIOS_DELIVERY_IDENTITY_ENABLED=1');try{if(($argv[7]??'')==='availability'){$partners->availability(new TrustedSyntheticPartner($argv[5]),$argv[5],(int)$argv[6],$argv[8]);}else{$partners->updateProfile(new TrustedSyntheticPartner($argv[5]),$argv[5],(int)$argv[6],'Synthetic concurrent');}echo 'PASS';}catch(DomainException){echo 'CONFLICT';}exit;
